class Solution:
    def longestAlmostPalindromicSubstring(self, s: str) -> int:
        n = len(s)
        def is_pal(l, r):
            while l < r:
                if s[l] != s[r]: return False
                l += 1; r -= 1
            return True
        def almost(l, r):
            while l < r and s[l] == s[r]:
                l += 1; r -= 1
            if l >= r: return True
            return is_pal(l + 1, r) or is_pal(l, r - 1)
        ans = 1
        for l in range(n):
            for r in range(l + 1, n):
                if almost(l, r):
                    ans = max(ans, r - l + 1)
        return ans

